import sys
def main():
    n = int(sys.stdin.read().strip())
    if n % 2 != 0:
        print(-1)
        return
    k = (n * (n - 1)) // 2
    print(k)
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i + j) % 2 == 0:
                x = (i + j) // 2
                print(4, i, j, x, (x + 1) % n + 1)
            else:
                print(3, i, j, (i + j) // 2 + 1)
